/* eslint-disable no-underscore-dangle, no-restricted-syntax */

'use strict';

// MODULES //

var inherit = require( '@stdlib/utils/inherit' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var REPL = require( '@stdlib/repl/base' );
var ShellSocket = require( './shell_socket.js' );
var ControlSocket = require( './control_socket.js' ); // switch it up with a worker
var IOPubSocket = require( './iopub_socket.js' );
var StdinSocket = require( './stdin_socket.js' );
var HBSocket = require( './hb_socket.js' ); // Should we create a separate socket primitive adjacent to the base Socket class? we import it like (socket).heartBeat, solely as it doesn't need any higher level decoding setups and just simply echoes back?
var handleExecuteRequest = require( './handlers/execute_request.js' );
var handleKernelInfoRequest = require( './handlers/kernel_info_request.js' );
var log = require( './custom_log.js' );


// MAIN //

/**
* Jupyter kernel constructor.
*
* @param {Options} options - constructor options (from the jupyter connection file)
* @returns {Kernel} kernel instance
*/
function Kernel( options ) {
	console.error("hello hello")
	// TODO: Read on 'starting' execution state on IOPub
	if ( !( this instanceof Kernel ) ) {
		return new Kernel( options );
	}

	// Call the parent constructor:
	REPL.call( this );

	// Initialize sockets:
	setNonEnumerableReadOnly( this, '_shellSocket', new ShellSocket( this, options ) );
	// setNonEnumerableReadOnly( 'this', '_controlSocket', new ControlSocket( this, options ) );
	setNonEnumerableReadOnly( this, '_ioPubSocket', new IOPubSocket( this, options ) );
	// setNonEnumerableReadOnly( 'this', '_stdinSocket', new StdinSocket( this, options ) );
	setNonEnumerableReadOnly( this, '_hbSocket', new HBSocket( this, options ) );

	// Start listening:
	this._shellSocket.listen();
	// this._controlSocket.listen();

	// Initialize request handlers:
	this.on( 'execute_request', this._handleExecuteRequest ); // Should they be prototype methods or just callbacks defined in the ctor itself?
	this.on( 'kernel_info_request', this._handleKernelInfoRequest );

	// Initialize heart beat:
	this._hbSocket.listen();

	return this;
}

/*
* Inherit from the `REPL` prototype.
*/
inherit( Kernel, REPL );

// Implementations of each handlers go here...

Kernel.prototype._handleExecuteRequest = function handle( message, content ) {
	var code;
	var self;

	self = this;

	this.once( 'command', onCommand );

	// TODO: Should we just deal with 'content' in handlers?, and deal with headers etc explicitly? Meaning we add, message.createReply(reply) in here itself
	this._ioPubSocket.setBusy( message );
	code = handleExecuteRequest( message );
	log( 'code is: '+code );

	this.emit( 'input', code );

	/**
	* Callback invoked upon executing a command.
	*
	* @private
	* @param {string} cmd - command
	* @param {boolean} success - boolean indicating whether the command successfully executed
	* @param {*} res - result
	*/
	function onCommand( cmd, success, res ) {
		var executeResult;
		var executeReply;
		var bundle;

		log( 'inside onCommand (juputer)' );
		executeReply = message.createReply( 'execute_reply', {
			'status': 'ok',
			'execution_count': self._count,
			'payload': [],
			'user_expressions': {}
		});

		// TODO: Temporary mime handling:
		switch ( typeof res ) {
		case 'object':
			bundle = {
				'text/plain': JSON.stringify( res, null, 2 ),
				'application/json': res
			}
			break;
		default:
			bundle = {
				'text/plain': String( res )
			}
		}

		executeResult = message.createReply( 'execute_result', {
			'execution_count': self._count,
			'data': bundle,
			'metadata': {}
		})

		this._shellSocket.send( executeReply );
		this._ioPubSocket.send( executeResult );
		this._ioPubSocket.setIdle( message );
	}
};

Kernel.prototype._handleKernelInfoRequest = function handle( message, content ) {
	var reply;

	// TODO: Should we just deal with 'content' in handlers?, and deal with headers etc explicitly? Meaning we add, message.createReply(reply) in here itself
	this._ioPubSocket.setBusy( message );
	reply = handleKernelInfoRequest( message );
	// console.error( JSON.stringify( reply ) );
	this._shellSocket.send( reply );
	this._ioPubSocket.setIdle( message );
};


// EXPORTS //

module.exports = Kernel;

